pub fn isEnabled() bool {
        return (switch (enabled) {
.yes => true,
.no => false,
.unknown => {
{
            enabled = detect: {
            if (bun.env_var.DO_NOT_TRACK.get()) {
                break :detect .no;
            }
            if ((bun.env_var.HYPERFINE_RANDOMIZED_ENVIRONMENT_OFFSET.get() != null)) {
                break :detect .no;
            }
            break :detect .yes;
};
            _ = bun.assert(((enabled == .yes) or (enabled == .no)));
            return (enabled == .yes);
        }
},
});
}

